---@class OverseaClubVCam3rdPersonFollowController
---@field VTarget                   UnityEngine.Transform 
---@field vcam3rdPersonFollow    Cinemachine.CinemachineVirtualCamera 
local OverseaClubVCam3rdPersonFollowController = Class('OverseaClubVCam3rdPersonFollowController')


function OverseaClubVCam3rdPersonFollowController:__init()
    self.isInit = false

    self.pitchMinDegree = -10
    self.pitchMaxDegree = 80

    self.cachedY = 0
    self.controller = nil
end



function OverseaClubVCam3rdPersonFollowController:__delete()
end


function OverseaClubVCam3rdPersonFollowController:Init(playerParams_, follow )
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    self.UpdateFunc = function()
        self:Update()
    end
    -- !!! 一个很凑巧的 时序位置, 恰好在 K控制器 Update() 的后面(90), cinemachine Brain 的 LateUpdate() 的前面
    self.behaviorExecutedAtOrder99 = KTool.GetComponent(self.controller.gameObject, typeof(BehaviorExecutedAtOrder99))
    self.behaviorExecutedAtOrder99:INTERNAL_Update( '+', self.UpdateFunc )

    -- ==============================
    assert( self.VTarget and self.vcam3rdPersonFollow )

    self.virtualTargetsController = CfUtils.GetLuaScr(self.VTarget.gameObject, "Game.UI.Club.Controller.OverseaClubVirtualTargetsController" )
    assert( self.virtualTargetsController )

    self.virtualTargetsController:Init(follow)
    self.followTF           = self.VTarget:Find("Follow")
    self.lookAt2TF          = self.VTarget:Find("LookAt2")
    self.lookAt2_ManualTF   = self.VTarget:Find("LookAt2_Manual")
    self.lookAt2_CodeTF     = self.VTarget:Find("LookAt2_Code")
    assert( self.lookAt2TF and self.lookAt2_ManualTF and self.followTF and self.lookAt2_CodeTF )

    self.viewRotateMode = ViewRotateMode.FromManual


    ---- 准备一些 辅助 tf:
    local newgo = GameObject( "helper_0" )
    self.helpTF = newgo.transform
    self.helpTF:SetParent( self.VTarget )
    ---
    local newgo2 = GameObject( "helper_up_correct" )
    self.upCorrectTF = newgo2.transform
    self.upCorrectTF:SetParent( self.VTarget )

    self.vcamParams_role     = VCam3rdPersonFollowParams.New({ 
        height = checkNumber(playerParams_.vcamHeight), radius = checkNumber(playerParams_.vcamRadius), shoulderOffset = playerParams_.vcamShoulderOffset
    })

    ---@type VCam3rdPersonFollowParams
    self.vcamParams_custom  = VCam3rdPersonFollowParams.New(self.vcamParams_role) -- 外部定制版参数, 比如钻洞时
    ---@type VCam3rdPersonFollowParams
    self.vcamParams_raw = VCam3rdPersonFollowParams.New(self.vcamParams_role)
    
    ---
    self._custom_t = 0 -- [0,1] 在 vcamParams_role 和 vcamParams_custom 之间插值;
    self.vcamParams_raw:Lerp( self.vcamParams_role, self.vcamParams_custom, self._custom_t )
    ---@type VCam3rdPersonFollowParams
    self.vcamParams_smooth  = VCam3rdPersonFollowParams.New(self.vcamParams_raw)

    -- cache:
    self._lastSmoothRadius = nil
    self._lastShoulderOffset = nil
    ----

    ---@type Cinemachine.Cinemachine3rdPersonFollow
    self.cinemachine3rdPersonFollow = DreamSpaceLuaUtils.GetCinemachineComponent( self.vcam3rdPersonFollow, typeof(Cinemachine3rdPersonFollow) )
    assert(self.cinemachine3rdPersonFollow)


    self.cachedDampingIntoCollision = self.cinemachine3rdPersonFollow.DampingIntoCollision

    self.lastFollowPos = self.followTF.position

    self.lookAt2TF.position = self.followTF.position + Vector3( 0, self.vcamParams_smooth.height, 0 )
    self.lookAt2_ManualTF.position = self.lookAt2TF.position
    self.lookAt2_CodeTF.position = self.lookAt2TF.position

    -- local initLookRotation = Quaternion.LookRotation( playerParams_.initLookDir, Vector3.up )
    -- self.lookAt2TF.rotation = initLookRotation
    -- self.lookAt2_ManualTF.rotation = initLookRotation
    -- self.lookAt2_CodeTF.rotation = initLookRotation
    self:SetLookDirectionImmediately( playerParams_.initLookDir )


    self.tgtLookAtRotationForCodeMode = Quaternion.identity -- 随便写个值

    ----------
    ---
    self.isInit = true
end

function OverseaClubVCam3rdPersonFollowController:SetFollow(follow)
    self.virtualTargetsController:SetFollow(follow)
end


function OverseaClubVCam3rdPersonFollowController:OnDestroy()

    self.behaviorExecutedAtOrder99:INTERNAL_Update( '-', self.UpdateFunc )
    self.UpdateFunc = nil

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end




-- ExecutionOrder: 110
function OverseaClubVCam3rdPersonFollowController:Update()
    if self.virtualTargetsController.isInit ~= true or self.isInit ~= true then 
        return
    end 

    local currentFollow = self.virtualTargetsController:GetCurrentFollow()
    self.followTF.position = currentFollow.position
    self.followTF.rotation = currentFollow.rotation

    ------

    self.vcamParams_raw:Lerp( self.vcamParams_role, self.vcamParams_custom, self._custom_t )

    local tmp_t = 0.1
    self.vcamParams_smooth.height           = Mathf.Lerp( self.vcamParams_smooth.height, self.vcamParams_raw.height, tmp_t )
    self.vcamParams_smooth.radius           = Mathf.Lerp( self.vcamParams_smooth.radius, self.vcamParams_raw.radius, tmp_t )
    self.vcamParams_smooth.shoulderOffset   = Vector3.Lerp( self.vcamParams_smooth.shoulderOffset, self.vcamParams_raw.shoulderOffset, tmp_t )


    local oldPos = self.lastFollowPos + Vector3( 0, self.vcamParams_smooth.height, 0 )
    local tgtPos = self.followTF.position + Vector3( 0, self.vcamParams_smooth.height, 0 )


    --self.lookAt2TF.position = Vector3.Lerp( self.lookAt2TF.position, tgtPos, 0.3 ) -- !!!
    --self.lookAt2TF.position = Vector3.Lerp( self.lookAt2TF.position, tgtPos, Time.fixedDeltaTime * 10 )
    --self.lookAt2TF.position = Vector3.MoveTowards( self.lookAt2TF.position, tgtPos, Time.deltaTime * 5 )

    self.lookAt2TF.position = tgtPos
    

    --self.lookAt2TF.position = OverseaClubVCam3rdPersonFollowController.SuperSmoothLerp( self.lookAt2TF.position, oldPos, tgtPos, Time.deltaTime, 20.0 )



    self.lastFollowPos = self.followTF.position


    ---
    self.lookAt2_ManualTF.position = self.lookAt2TF.position
    self.lookAt2_CodeTF.position = self.lookAt2TF.position
    

    if self.viewRotateMode == ViewRotateMode.FromManual then 
        self.lookAt2TF.rotation = Quaternion.Slerp( self.lookAt2TF.rotation, self.lookAt2_ManualTF.rotation, 0.3 )
        self:_CorrectTheUpDirection( self.lookAt2TF )
    else 
        -- todo: 目前 暂不会进入此模式
        self.lookAt2_CodeTF.rotation = Quaternion.Slerp( self.lookAt2_CodeTF.rotation, self.tgtLookAtRotationForCodeMode, 0.2 )
        self.lookAt2TF.rotation = self.lookAt2_CodeTF.rotation
    end 

    ---
    if isNull(self._lastSmoothRadius) or  Mathf.Approximately(self._lastSmoothRadius, self.vcamParams_smooth.radius) == false then 
        --print("改 radius")
        self._lastSmoothRadius = self.vcamParams_smooth.radius
        self.cinemachine3rdPersonFollow.CameraDistance = self.vcamParams_smooth.radius
    end

    ---
    if isNull(self._lastShoulderOffset) or self._lastShoulderOffset ~= self.vcamParams_smooth.shoulderOffset then 
        --print("改 shoulderOffset")
        self._lastShoulderOffset = self.vcamParams_smooth.shoulderOffset
        self.cinemachine3rdPersonFollow.ShoulderOffset = self.vcamParams_smooth.shoulderOffset
    end
end

