---@param lookDir_ UnityEngine.Vector3
function OverseaClubVCam3rdPersonFollowController:SetLookDirectionImmediately( lookDir_ )
    local initLookRotation = Quaternion.LookRotation( lookDir_, Vector3.up )
    self.lookAt2TF.rotation = initLookRotation
    self.lookAt2_ManualTF.rotation = initLookRotation
    self.lookAt2_CodeTF.rotation = initLookRotation
end



-- oldSelfPos_ is the follower's old position, oldTgtPos_ is the target's old position, newTgtPos_ is the target's new position, t is the elapsed time, and k is the lerp rate
--Vector3 SuperSmoothLerp(Vector3 oldSelfPos_, Vector3 oldTgtPos_, Vector3 newTgtPos_, float deltaTime_, float k)
function OverseaClubVCam3rdPersonFollowController.SuperSmoothLerp( oldSelfPos_, oldTgtPos_, newTgtPos_, deltaTime_, k )
    local kt = k * deltaTime_
    local f = oldSelfPos_ - oldTgtPos_ + (newTgtPos_ - oldTgtPos_) / kt
    return newTgtPos_ - (newTgtPos_ - oldTgtPos_) / kt + f * Mathf.Exp( - kt)
end


function OverseaClubVCam3rdPersonFollowController:SetPitchDegree( minDegree_, maxDegree_ )
    self.pitchMinDegree = minDegree_
    self.pitchMaxDegree = Mathf.Max( maxDegree_, self.pitchMinDegree )
end

---@param custom_params_ table @ { height : number, radius : number, shoulderOffset : Vector3 }
function OverseaClubVCam3rdPersonFollowController:SetCustomVCamParams( custom_params_ )
    self.vcamParams_custom:CopyParamsFrom(custom_params_)
end


function OverseaClubVCam3rdPersonFollowController:SetCustomT( new_t_ )
    self._custom_t = new_t_
end


---@param lookAtDir_ UnityEngine.Vector3
function OverseaClubVCam3rdPersonFollowController:SetLookAt2_ManualTF( lookAtDir_ )
    self.lookAt2_ManualTF.rotation = Quaternion.LookRotation( lookAtDir_, Vector3.up )
end


function OverseaClubVCam3rdPersonFollowController:SetDampingIntoCollision()
    self.cinemachine3rdPersonFollow.DampingIntoCollision = 3 -- 一个足够大的值, 以便让 vcam3rd 相机不被墙壁卡
end

function OverseaClubVCam3rdPersonFollowController:ResetDampingIntoCollision()
    self.cinemachine3rdPersonFollow.DampingIntoCollision = self.cachedDampingIntoCollision
end




function OverseaClubVCam3rdPersonFollowController:SwitchViewRotateMode( isManualMode_ )
    if isManualMode_ == true then 
        self.viewRotateMode = ViewRotateMode.FromManual
        self.lookAt2_ManualTF.rotation = self.lookAt2TF.rotation
    else 
        self.viewRotateMode = ViewRotateMode.FromCode
        self.lookAt2_CodeTF.rotation = self.lookAt2TF.rotation
    end
end



-- 新相机 旋转
---@param xDelta_ System.Single @ yaw 值, right 为正 
---@param yDelta_ System.Single @ pitch 值, up 为正 
function OverseaClubVCam3rdPersonFollowController:Rotate( xDelta_, yDelta_ )
    if self.isInit ~= true then 
        return
    end 

    local _lookAt = self.lookAt2_ManualTF
    -----
    _lookAt:Rotate( Vector3.up,     xDelta_, Space.World )
    
    local forwardHorizon = Vector3.ProjectOnPlane(_lookAt.forward, Vector3.up).normalized
    local angle = Vector3.SignedAngle( forwardHorizon, _lookAt.forward, _lookAt.right ) -- 相机俯视时为正数, 此时 _lookAt 看下下半球
    angle = angle + yDelta_

    local canPitch =    (yDelta_ >= 0 and angle <  self.pitchMaxDegree ) or   -- 相机愈发俯视时
                        (yDelta_ <  0 and angle >= self.pitchMinDegree )      -- 相机愈发仰视时
    if canPitch == true then 
        _lookAt:Rotate( Vector3.right,  yDelta_, Space.Self )
    end 

    -- 上面两步转完后, transform 会歪掉; 解法就是用 LookAt() 再次掰正
    self:_CorrectTheUpDirection(_lookAt)    
end


---@param tf_ UnityEngine.Transform
function OverseaClubVCam3rdPersonFollowController:_CorrectTheUpDirection( tf_ )
    self.upCorrectTF.position = tf_.position + tf_.forward
    tf_:LookAt( self.upCorrectTF, Vector3.up )
end



-- 检测 vcam3rdPersonFollow 是否为 live 相机
-- 当从 vcam1 转换为 vcam2, 且模式不为 cut, 存在转换过程时:
-- 转换前: vcam1, vcam2 的 live 分别为 { true, false }
-- 转换中: vcam1, vcam2 的 live 分别为 { true, true }
-- 转换后: vcam1, vcam2 的 live 分别为 { false, true }
function OverseaClubVCam3rdPersonFollowController:IsVCamLive()
    return CinemachineCore.Instance:IsLive( self.vcam3rdPersonFollow )
end


return OverseaClubVCam3rdPersonFollowController
